 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Locate the 2x2 zero aperture; its rows and columns are the erase bands.
    anchor = None
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                anchor = (r, c)
                break
        if anchor is not None:
            break
    if anchor is None:
        return out
    r, c = anchor
    rows, cols = {r, r + 1}, {c, c + 1}
    for i in range(h):
        for j in range(w):
            if (i in rows or j in cols) and grid[i][j] != 2:
                out[i][j] = 0
    return out
